theorem imo_2006_p3 :
    IsLeast {M : ℝ | ∀ a b c : ℝ,
      abs (a * b * (a ^ 2 - b ^ 2) + b * c * (b ^ 2 - c ^ 2) + c * a * (c ^ 2 - a ^ 2)) ≤
        M * (a ^ 2 + b ^ 2 + c ^ 2) ^ 2}
      answer(9 * Real.sqrt 2 / 32) := by
  let M : ℝ := 9 * Real.sqrt 2 / 32;
  intro a b c;
  have h0: (a^2 + b^2 + c^2) ≠ 0 ∨ a = b = c := by
    contrapose! h; assume h: a^2 + b^2 + c^2 = 0 ∧ a ≠ b ∨ a ≠ c;
    have h1: (a^2 + b^2 + c^2) = 0 from h.left;
    have h2: a = 0 ∧ b = 0 ∧ c = 0 := by linext; simp [h1];
    contradiction;

  have h1: (a^2 + b^2 + c^2) = 0 → abs(...) ≤ M * (a^2 + b^2 + c^2)^2 :=
    by intro h; unfold h; simp [abs_zero, pow_zero]; exact le_rfl;

  have h2: (a^2 + b^2 + c^2) ≠ 0 → abs(...) ≤ M * (a^2 + b^2 + c^2)^2 := by
    intro h;
    let d : ℝ := a^2 + b^2 + c^2;
    have hd: d > 0 := by linext; simp [h];
    let e : ℝ := abs (a * b * (a ^ 2 - b ^ 2) + b * c * (b ^ 2 - c ^ 2) + c * a * (c ^ 2 - a ^ 2));
    have he: e ≤ M * d^2;
    let a' := a / sqrt(d);
    let b' := b / sqrt(d);
    let c' := c / sqrt(d);
    have h3: (a'^2 + b'^2 + c'^2) = 1;
    have he': abs (a' * b' * (a'^2 - b'^2) + b' * c' * (b'^2 - c'^2) + c' * a' * (c'^2 - a'^2)) ≤ M :=
      by
        let expr := a' * b' * (a'^2 - b'^2) + b' * c' * (b'^2 - c'^2) + c' * a' * (c'^2 - a'^2);
        have h4: abs(expr) ≤ M :=
          by
            let x := a' / sqrt(1); -- Since a'^2 + b'^2 + c'^2 = 1, we can parametrize with spherical coordinates.
            let y := b' / sqrt(1);
            let z := c' / sqrt(1);
            have h5: (x^2 + y^2 + z^2) = 1;
            let expr2 := x * y * (x^2 - y^2) + y * z * (y^2 - z^2) + z * x * (z^2 - x^2);
            have h6: abs(expr2) ≤ M :=
              by
                -- Use symmetry to find maximum of |expr2| under constraint x² + y² + z² = 1.
                let θ := π / 4;
                let φ := π / 4;
                let ψ := π / 4;
                have h7: abs(expr2) ≤ M :=
                  by
                    let x := cos(θ);
                    let y := sin(θ) * cos(φ);
                    let z := sin(θ) * sin(φ) * cos(ψ);
                    let expr3 := x * y * (x^2 - y^2) + y * z * (y^2 - z^2) + z * x * (z^2 - x^2);
                    have h8: abs(expr3) = M;
                    exact h8;
                exact h6;
            exact h4;
    have h5: e ≤ M * d^2 := by
      simp [he', he];
      field_simp [sqrt_d];
      nlinarith;

  exact (h1 _ _ _ ∨ h2 _ _ _)

theorem amc12_2001_p9 (f : ℝ → ℝ) (h₀ : ∀ x > 0, ∀ y > 0, f (x * y) = f x / y) (h₁ : f 500 = 3) :
    f 600 = answer(5 / 2) := by
  let x := 500;
  let y := 6 / 5;
  have h2 : (x * y) = 600 := by norm_num;
  have h3 : y > 0 := by norm_num;
  have h4 : x > 0 := by norm_num;
  have h5 : f 600 = f (x * y) / y :=
    calc
      f 600 = f (x * y)     := h2.symm ▸ rfl
      ... = f x / y         := h₀ x h3
  calc
    f 600 = f (x * y) / y      := h5
    ... = 3 / (6 / 5)          := h₁
    ... = 3 * (5 / 6)          := by field_simp [mul_div_eq_mul_div]
    ... = answer(5 / 2)        : rfl

theorem amc12a_2010_p22 :
    IsLeast { ∑ k in Finset.Icc 1 119, abs (k * x - 1) | x : ℝ } (1 / 119) := by
  let f (x : ℝ) := ∑ k in Finset.Icc 1 119, abs (k * x - 1)
  let m := 1 / 119 -- The value of x that minimizes the sum

  have h_min: ∀ ε > 0, ∃ δ > 0, ∀ x ∈ Ioo m δ, f x ≥ f m :=
    by intro ε; assume hε : ε > 0;
    let δ := ε / 119;
    use δ;
    intros x hx;
    have h: |x - m| < δ → ∑ k in Finset.Icc 1 119, abs (k * x - 1) ≥ f m :=
      by intro h; 
      apply nlinarith;
      have h2: ∀ k ∈ Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| ≥ |k * (x - m)| := 
        by intros k hk; 
        simp [abs_sub];
        exact le_rfl;
      have h3: ∑ k in Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| ≥ ∑ k in Finset.Icc 1 119, |k * (x - m)| :=
        by simp;
      have h4: ∑ k in Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| = ∑ k in Finset.Icc 1 119, |k * x - 1| + ∑ k in Finset.Icc 1 119, |k * m - 1| :=
        by simp;
      have h5: ∑ k in Finset.Icc 1 119, |k * m - 1| = f m := 
        by simp [f];
      exact (h3.trans h4).trans h5;
    exact h;

  have h_max: ∀ ε > 0, ∃ δ > 0, ∀ x ∈ Ioo (m + ε) δ, f x ≥ f m :=
    by intro ε; assume hε : ε > 0;
    let δ := ε / 119;
    use δ;
    intros x hx;
    have h: |x - m| < δ → ∑ k in Finset.Icc 1 119, abs (k * x - 1) ≥ f m :=
      by intro h; 
      apply nlinarith;
      have h2: ∀ k ∈ Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| ≥ |k * (x - m)| := 
        by intros k hk; 
        simp [abs_sub];
        exact le_rfl;
      have h3: ∑ k in Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| ≥ ∑ k in Finset.Icc 1 119, |k * (x - m)| :=
        by simp;
      have h4: ∑ k in Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| = ∑ k in Finset.Icc 1 119, |k * x - 1| + ∑ k in Finset.Icc 1 119, |k * m - 1| :=
        by simp;
      have h5: ∑ k in Finset.Icc 1 119, |k * m - 1| = f m := 
        by simp [f];
      exact (h3.trans h4).trans h5;
    exact h;

  have h_cont: ContinuousOn f (Ici m) := 
    by apply continuous_on_sum; 
    intro k; 
    apply continuous_on_abs; 
    apply continuous_mul_left; 
    assume x; 
    use (x : ℝ); 
    exact (continuous_id _).comp (continuous_const _);

  have h_ger: IsGreatest f m := 
    by refine ⟨_, _⟩;
    · intros ε hε;
      use (m + ε);
      have h1: ∑ k in Finset.Icc 1 119, abs (k * x - 1) ≥ f m :=
        by intro x; 
        apply nlinarith;
        have h2: ∀ k ∈ Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| ≥ |k * (x - m)| := 
          by intros k hk; 
          simp [abs_sub];
          exact le_rfl;
        have h3: ∑ k in Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| ≥ ∑ k in Finset.Icc 1 119, |k * (x - m)| :=
          by simp;
        have h4: ∑ k in Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| = ∑ k in Finset.Icc 1 119, |k * x - 1| + ∑ k in Finset.Icc 1 119, |k * m - 1| :=
          by simp;
        have h5: ∑ k in Finset.Icc 1 119, |k * m - 1| = f m := 
          by simp [f];
        exact (h3.trans h4).trans h5;
      exact h1;

    · intros ε hε;
      use (m - ε);
      have h1: ∑ k in Finset.Icc 1 119, abs (k * x - 1) ≥ f m :=
        by intro x; 
        apply nlinarith;
        have h2: ∀ k ∈ Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| ≥ |k * (x - m)| := 
          by intros k hk; 
          simp [abs_sub];
          exact le_rfl;
        have h3: ∑ k in Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| ≥ ∑ k in Finset.Icc 1 119, |k * (x - m)| :=
          by simp;
        have h4: ∑ k in Finset.Icc 1 119, |(k * x - 1)| + |k * m - 1| = ∑ k in Finset.Icc 1 119, |k * x - 1| + ∑ k in Finset.Icc 1 119, |k * m - 1| :=
          by simp;
        have h5: ∑ k in Finset.Icc 1 119, |k * m - 1| = f m := 
          by simp [f];
        exact (h3.trans h4).trans h5;
      exact h1;

  have h_isleast: IsLeast {f x | x : ℝ} m := 
    by refine ⟨_, _⟩;
    · use m;
      exact h_ger;
    · intros a ha;
      sorry; -- Need to show that if f(a) < f(m), then a = m

  exact h_isleast

theorem mathd_numbertheory_37 : Nat.lcm 9999 100001 = answer(90900909) := by
  have h : Nat.gcd 9999 100001 = 101 := by norm_num;
  have eq : (9999 * 100001) / 101 = 90900909 := by
    rw [Nat.div_eq_iff_mul_left];
    norm_num;
  rw [Nat.lcm_eq_div_gcd];
  exact Nat.eq_of_dvd_left (9999 * 100001) 101 h;

theorem aime_1983_p9 (x : ℝ) (h₀ : 0 < x ∧ x < Real.pi) :
    IsLeast
      {(9 * (x ^ 2 * Real.sin x ^ 2) + 4) / (x * Real.sin x) | (x : ℝ) (hx : 0 < x ∧ x < Real.pi) }
      answer(12) := by
  -- Strategy:
  -- 1. Simplify the expression to f(x) = 9x sin x + 4/(x sin x)
  -- 2. Use AM-GM inequality on the terms 9x sin x and 4/(x sin x)
  --    Let a = 9x sin x, b = 4/(x sin x), then f(x) = a + b
  -- 3. Apply AM-GM: (a + b)/2 ≥ √(ab) → a + b ≥ 2√(ab)
  --    Compute ab = 9x sin x * 4/(x sin x) = 36, so √(ab) = 6
  -- 4. Therefore f(x) ≥ 12, with equality when a = b → 9x sin x = 4/(x sin x)
  --    Solve this to find the minimum occurs at that point.
  -- 5. Show that the set of values is bounded below by 12 and achieves it
  --    Hence, 12 is the least value.

  let f : ℝ → ℝ := λ x, (9 * (x ^ 2 * Real.sin x ^ 2) + 4) / (x * Real.sin x)
  have h2: ∀ x ∈ (0, π), f x ≥ 12 :=
    by {
      simp [f],
      field_simp,
      nlinarith,
    }

  let a : ℝ := 9 * x * Real.sin x
  let b : ℝ := 4 / (x * Real.sin x)
  have h3: a + b = f x :=
    by {
      simp [f, a, b],
      field_simp,
    }

  -- AM-GM inequality on a and b
  have h4: a + b ≥ 2 * sqrt(a * b) :=
    by {
      apply real.am_gm (a : ℝ) (b : ℝ),
      norm_num,
    }

  let ab : ℝ := a * b
  have h5: ab = 36 :=
    by {
      simp [a, b],
      field_simp,
      nlinarith,
    }

  have h6: sqrt(ab) = 6 :=
    by {
      apply real.sqrt_eq (ab : ℝ),
      norm_num,
    }

  have h7: a + b ≥ 12 :=
    by {
      rw [h4, h6],
      linarith,
    }

  -- Since f x = a + b and a + b ≥ 12, then f x ≥ 12
  let f_min : ℝ := 12
  have h8: ∃ x ∈ (0, π), f x = 12 :=
    by {
      use (π / 2)
      have h9: 0 < π / 2 ∧ π / 2 < π :=
        by {
          norm_num,
        }
      exact ⟨h9, by {
        simp [a, b],
        field_simp,
        nlinarith,
      }⟩
    }

  let min_val := answer(12)
  exact IsLeast.mk f_min h2 h8

theorem mathd_numbertheory_269 : (2005 ^ 2 + 2005 ^ 0 + 2005 ^ 0 + 2005 ^ 5) % 100 = 52 := by
  -- Compute each term modulo 100 using properties of modular arithmetic.
  -- Since (a + b) mod m = ((a mod m) + (b mod m)) mod m, we can compute each power mod 100.

  let a : ℕ := 2005 ^ 2
  let b : ℕ := 2005 ^ 0
  let c : ℕ := 2005 ^ 0
  let d : ℕ := 2005 ^ 5

  have h_a : a % 100 = 25 :=
    by {
      norm_num,
    }

  have h_b : b % 100 = 1 :=
    by {
      norm_num,
    }

  have h_c : c % 100 = 1 :=
    by {
      norm_num,
    }

  have h_d : d % 100 = 25 :=
    by {
      let x : ℕ := 2005
      have h_x : x % 100 = 5 :=
        by {
          norm_num,
        }
      let p5 : ℕ := 5 ^ 5
      have h_p5 : p5 % 100 = 3125 % 100 := by norm_num
      have h_p5_mod_100 : 3125 % 100 = 25 :=
        by {
          norm_num,
        }
    }

  have h_total : (a + b + c + d) % 100 = ((a % 100) + (b % 100) + (c % 100) + (d % 100)) % 100 :=
    by {
      norm_num,
    }

  let total_mod_100 : ℕ := (25 + 1 + 1 + 25) % 100
  have h_sum : total_mod_100 = 52 :=
    by {
      norm_num,
    }

  exact h_sum

theorem mathd_algebra_410 :
    IsLeast {y : ℝ | ∃ x : ℝ, y = x ^ 2 - 6 * x + 13} 4 := by
  -- We want to show that the minimum value of the quadratic function f(x) = x^2 - 6x + 13 is 4.
  let a := 1;
  let b := -6;
  let x_min := -(b) / (2 * a);
  have h_x_min : x_min = 3 := by norm_num;

  -- Evaluate the function at x = 3 to find the minimum value.
  have h_min_val : (x_min ^ 2 - 6 * x_min + 13) = 4 :=
    by
      ring;

  -- Show that 4 is in the set {y | ∃x, y = x^2 - 6x + 13} since it's achieved at x = 3.
  have h_in_set : 4 ∈ {y | ∃x : ℝ, y = x ^ 2 - 6 * x + 13} :=
    ⟨3, by rw [h_min_val]⟩;

  -- Show that for all y in the set, y ≥ 4.
  intros y h_y;
  have h_y_eq : ∃x, y = x^2 - 6*x + 13 := h_y;
  let x := classical.some h_y_eq;
  have h_x : y = x^2 - 6*x + 13 := classical.some_spec h_y_eq;

  -- Complete the square to show that y ≥ 4.
  have h_complete_square : y = (x - 3)^2 + 4 :=
    by
      ring;

  -- Since squares are non-negative, (x - 3)^2 ≥ 0 ⇒ y ≥ 4.
  nlinarith;

  -- Therefore, 4 is the least value in the set.
  exact IsLeast.intro h_in_set this
